/// <summary>
/// Externsion class of form data source SalesTable in form ReturnTable
/// </summary>
[ExtensionOf(formDataSourceStr(ReturnTable, SalesTable))]
internal final class METReturnTableFormSalesTableDS_Extension
{
}

Method.Source:
/// <summary>
/// Performs write action on the datasource to peform insert of active record.
/// </summary>
public void write()
{
    next write();
    FormDataSource fds = this;
    FormDataSource fdsMETSalesTable_ExtFields = fds.formRun().dataSource(formDataSourceStr(SalesTable, METSalesTable));
    SalesTable salesTable = fds.cursor();

    if (fdsMETSalesTable_ExtFields && METSalesTable::findBySalesTable(salesTable.RecId).RecId == 0 )
    {
        METSalesTable metSalesTableLocal = fdsMETSalesTable_ExtFields.cursor();
        salesTable.metPackMETSalesTable(metSalesTableLocal);
        metSalesTableLocal.SysExtensionSerializerExtensionMap::insertAfterBaseTable(salesTable);
    }
}

/// <summary>
/// Create method override to reread reference data source
/// </summary>
/// <param name = "append">boolean</param>
void create(boolean append)
{
    next create(append);

    SalesTable salesTable = this.cursor();
    FormDataSource fdsMETSalesTable_ExtFields = this.formRun().dataSource(formDataSourceStr(SalesTable, METSalesTable));
    METSalesTable metSalesTableCursor = fdsMETSalesTable_ExtFields.cursor();

    metSalesTableCursor.data(SysExtensionSerializerExtensionMap::findByBase(
        metSalesTableCursor.TableId,
        SalesTable.RecId,
        true));

    fdsMETSalesTable_ExtFields.rereadReferenceDataSources();
}
